INSERT INTO VISIT (visit_id, appointment_id, patient_id, doctor_id, visit_date, symptoms, blood_pressure, pulse_rate, temperature_f, weight_kg, doctor_notes) VALUES
(1, 1, 1, 1, '2026-10-15 10:00:00', 'Chest heaviness on fast walking, mild sweating', '140/90', 82, 98.4, 76.5, 'Advised lipid profile, 12-lead ECG, prescribed statin & anti-hypertensive.'),
(2, 2, 2, 5, '2026-10-15 10:30:00', 'Tiredness, excessive thirst, polyuria', '130/84', 76, 98.6, 68.0, 'Type 2 Diabetes Mellitus under review. Advised HbA1c and adjusted Metformin.'),
(3, 3, 3, 2, '2026-10-16 11:30:00', 'Throbbing unilateral headache, light sensitivity', '120/80', 74, 98.2, 72.0, 'Diagnosed migraine. Scheduled Brain MRI to rule out secondary etiology.'),
(4, 4, 4, 3, '2026-10-16 15:00:00', 'Bilateral knee crepitus, difficulty squatting', '124/82', 78, 98.6, 64.5, 'Osteoarthritis Grade II in left knee. Advised knee X-ray and calcium supplements.'),
(5, 5, 5, 1, '2026-10-17 10:30:00', 'Occipital headache in morning, BP consistently above 150', '156/96', 88, 98.4, 84.0, 'Essential Stage 2 Hypertension. Initiated Telmisartan 40mg and lifestyle modifications.'),
(6, 6, 6, 4, '2026-10-17 12:00:00', 'Moderate fever, inflamed pharynx, dry cough', '108/70', 94, 100.8, 22.0, 'Acute upper respiratory tract infection. Paracetamol and pediatric cough syrup prescribed.'),
(7, 7, 7, 5, '2026-10-18 09:30:00', 'High fasting sugars (>200 mg/dL), blurred vision', '138/88', 80, 98.6, 80.0, 'Diabetic dyslipidemia. Added Glimepiride and ordered fasting glucose + lipid panel.'),
(8, 8, 8, 3, '2026-10-18 15:30:00', 'Sharp lumbar pain with radiation to calf', '118/76', 72, 98.4, 55.0, 'Suspected Lumbar Radiculopathy (L4-L5). Prescribed Pregabalin and physical therapy.'),
(9, 9, 9, 6, '2026-10-19 11:30:00', 'Mild lethargy, no active nausea or vomiting', '122/78', 75, 98.6, 62.0, 'Oncology maintenance review. Ordered CBC, LFT, and Kidney Function Test.'),
(10, 10, 10, 1, '2026-10-19 12:30:00', 'Fluttering chest feeling, occasional dizziness', '132/86', 96, 98.6, 70.0, 'Sinus tachycardia with ectopic beats. Advised 2D Echo and 12-lead ECG.'),
(11, 11, 11, 2, '2026-10-20 11:00:00', 'Peripheral neuropathy in fingers, decreased grip strength', '142/90', 78, 98.4, 75.0, 'Cervical radiculopathy vs carpal tunnel syndrome. Prescribed neurovitamins and nerve conduction study.'),
(12, 12, 12, 5, '2026-10-20 14:30:00', 'Epigastric burning sensation, water brash', '120/78', 74, 98.6, 58.0, 'Gastroesophageal Reflux Disease (GERD). Prescribed Pantoprazole 40mg before meals.'),
(13, 13, 13, 3, '2026-10-21 16:30:00', 'Restricted range of motion in right arm, night pain', '128/82', 76, 98.4, 71.0, 'Rotator cuff tendinitis / frozen shoulder stage 1. Advised topical analgesics and shoulder exercises.'),
(14, 14, 14, 4, '2026-10-21 10:30:00', 'Routine immunization and healthy developmental parameters', '100/68', 92, 98.4, 14.2, 'Administered pediatric booster. Normal developmental milestones.'),
(15, 15, 15, 1, '2026-10-22 10:00:00', 'Good exercise tolerance, no chest pain', '126/80', 70, 98.6, 73.0, 'Post-PTCA stable cardiac condition. Continuing Aspirin, Statin, and Beta-blocker.'),
(16, 16, 16, 5, '2026-10-22 11:30:00', 'Diffuse myalgia, low-grade pyrexia, shivering', '122/80', 84, 99.8, 61.0, 'Viral syndrome with arthralgia. Advised CBC, hydration, and Paracetamol.'),
(17, 17, 17, 7, '2026-10-23 11:00:00', 'Borderline elevated BP, occasional breathlessness', '144/92', 80, 98.4, 79.0, 'Hypertensive heart disease evaluation. Ordered 12-lead ECG and lipid screen.'),
(18, 18, 18, 8, '2026-10-23 16:00:00', 'Nocturnal cough and breathlessness during play', '105/70', 88, 98.6, 28.0, 'Mild persistent bronchial asthma. Prescribed Montelukast-Levocetirizine and inhaler.'),
(19, 19, 19, 9, '2026-10-24 12:00:00', 'Severe neck stiffness radiating to left shoulder', '134/86', 74, 98.4, 69.0, 'Cervical spondylotic changes. Prescribed muscle relaxant and cervical isometric exercises.'),
(20, 20, 20, 10, '2026-10-24 16:30:00', 'Spiking temperature (102°F), headache, retro-orbital pain', '116/74', 102, 102.2, 59.0, 'Acute febrile illness. Urgent CBC, Dengue NS1 antigen and malaria card test ordered.');
