INSERT INTO PRESCRIPTION (prescription_id, visit_id, doctor_id, patient_id, prescription_date, advice_notes) VALUES
(1, 1, 1, 1, '2026-10-15', 'Take low-salt diet, daily 30-minute brisk walk, avoid smoking'),
(2, 2, 5, 2, '2026-10-15', 'Strict low-carbohydrate diet, self-monitor blood glucose twice weekly'),
(3, 3, 2, 3, '2026-10-16', 'Avoid screen exposure during attacks, maintain hydration'),
(4, 4, 3, 4, '2026-10-16', 'Avoid cross-legged sitting and deep squatting; use western toilet'),
(5, 5, 1, 5, '2026-10-17', 'Monitor blood pressure every alternate morning, reduce dietary sodium'),
(6, 6, 4, 6, '2026-10-17', 'Warm water gargling, steam inhalation twice a day'),
(7, 7, 5, 7, '2026-10-18', 'Maintain meal timings and repeat fasting profile after 4 weeks'),
(8, 8, 3, 8, '2026-10-18', 'Use firm mattress, avoid lifting heavy luggage'),
(9, 9, 6, 9, '2026-10-19', 'Ensure high protein nutrition and hygienic home food'),
(10, 10, 1, 10, '2026-10-19', 'Avoid excessive caffeine, tea, and energy drinks'),
(11, 11, 2, 11, '2026-10-20', 'Wear wrist splint while sleeping, nerve stretching exercise'),
(12, 12, 5, 12, '2026-10-20', 'Eat dinner at least 2.5 hours before sleeping, avoid oily snacks'),
(13, 13, 3, 13, '2026-10-21', 'Ice compression for 15 minutes twice daily, pendulum exercises'),
(14, 14, 4, 14, '2026-10-21', 'Adequate hydration, fruit puree, and vitamin rich diet'),
(15, 15, 1, 15, '2026-10-22', 'Continue cardioprotective medication regimen without missed doses'),
(16, 16, 5, 16, '2026-10-22', 'Ample rest, consume electral/ORS fluids, soft diet'),
(17, 17, 7, 17, '2026-10-23', 'Regular aerobic exercise, stress reduction techniques'),
(18, 18, 8, 18, '2026-10-23', 'Keep inhaler accessible at school/travel, avoid sudden cold air'),
(19, 19, 9, 19, '2026-10-24', 'Ergonomic computer setup, use orthopedic neck pillow'),
(20, 20, 10, 20, '2026-10-24', 'Tepid sponging if temperature exceeds 101°F, plenty of coconut water');
